window.docContents[40].resolve({"/rules/PL1001/#PL1001-proof-shape":{"contents":"A conditional result must carry the assumption in its type, for example ∀ (h : P), Q, so the exact theorem statement shows what it depends on. Its transitive axiom set must then fit the surface's foundation profile.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1001: Project logical axioms are forbidden","header":"Required proof shape","id":"/rules/PL1001/#PL1001-proof-shape"}});